pub const UPDATE_ASSET_BASE: &str = r"UPDATE assets
SET name = COALESCE(?1, name),
    identifier = COALESCE(?2, identifier),
    classifier = COALESCE(?3, classifier),
    forced_usd_price = CASE
      WHEN CAST(?4 AS BOOLEAN) = 1 THEN ?5
      WHEN CAST(?6 AS BOOLEAN) = 1 THEN NULL
      ELSE forced_usd_price
    END,
    tracking_ticker = CASE
      WHEN CAST(?7 AS TEXT) IS NOT NULL THEN NULLIF(CAST(?7 AS TEXT), '')
      ELSE tracking_ticker
    END,
    tracking_multiplier = COALESCE(?8, tracking_multiplier),
    user_edited = 1,
    last_price = CASE WHEN CAST(?9 AS BOOLEAN) = 1 OR CAST(?7 AS TEXT) IS NOT NULL OR ?8 IS NOT NULL THEN NULL ELSE last_price END,
    last_price_at = CASE WHEN CAST(?9 AS BOOLEAN) = 1 OR CAST(?7 AS TEXT) IS NOT NULL OR ?8 IS NOT NULL THEN NULL ELSE last_price_at END,
    price_connectivity = CASE
      WHEN ?2 IS NOT NULL OR CAST(?7 AS TEXT) IS NOT NULL THEN 'HEALTHY'
      ELSE COALESCE(?10, price_connectivity)
    END,
    investment_connectivity = CASE
      WHEN CAST(?11 AS BOOLEAN) = 1 THEN 'HEALTHY'
      ELSE COALESCE(?12, investment_connectivity)
    END,
    updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now')
WHERE id = ?13";
