pub const ASSET_RECORDS: &str = r"WITH latest_holdings AS (
  SELECT h.asset_id
  FROM asset_daily_holdings h
  JOIN account_balance_daily_snapshots s ON s.id = h.snapshot_id
  JOIN accounts ha ON ha.id = h.account_id
  WHERE ha.is_hidden = 0
    AND ha.is_closed = 0
    AND h.counts_toward_value = 1
    AND s.date = (SELECT MAX(s2.date) FROM account_balance_daily_snapshots s2 WHERE s2.account_id = s.account_id)
  GROUP BY h.asset_id
)
SELECT a.additional, a.asset_type, a.classifier, a.created_at, a.forced_usd_price, a.id, a.identifier, a.investment_connectivity, a.last_price, a.last_price_at, a.name, a.price_connectivity, a.tracking_multiplier, a.tracking_ticker, a.updated_at, a.user_created, a.user_edited
FROM assets a
LEFT JOIN latest_holdings lh ON lh.asset_id = a.id
JOIN assets_fts ON assets_fts.rowid = a.id AND assets_fts MATCH ?1 -- :if $1
WHERE
  (lh.asset_id IS NOT NULL OR a.user_created = 1) -- :if $7
  AND a.asset_type = ?2 -- :if $2
  AND a.price_connectivity = ?3 -- :if $3
  AND a.investment_connectivity = ?4 -- :if $4
  AND (instr(lower(coalesce(a.name, '')), ?5) > 0 OR instr(lower(a.identifier), ?6) > 0) -- :if $8
ORDER BY
  bm25(assets_fts) ASC, -- :if $1
  lower(coalesce(a.name, '')) ASC, -- :if $9
  a.identifier ASC, -- :if $9
  a.id ASC";
