pub const CONNECTIONS: &str = r"SELECT c.id, c.source_table, c.source_id, c.name, c.owner_id, o.name AS owner_name, c.is_active
FROM connections c
JOIN owners o ON o.id = c.owner_id
WHERE
  c.source_table IN ('plaid_items', 'evm_wallets', 'simplefin_connections') -- :if $4
  AND c.is_active = 1 -- :if $5
  AND c.id IN (/*SLICE:ids*/?1) -- :if $1
  AND c.source_table = ?2 -- :if $6
  AND c.source_id = ?3 -- :if $6
ORDER BY c.id";
static CONNECTIONS_DYN: std::sync::LazyLock<dynfilter::Compiled> = std::sync::LazyLock::new(|| {
    dynfilter::compile_with_arg_order(
        CONNECTIONS,
        dynfilter::Placeholders::NumberedSqlite,
        dynfilter::Dialect::Sqlite,
        &[1usize, 2usize, 3usize],
        &[dynfilter::Clause {
            header: 3usize,
            connector: dynfilter::Connector::And,
            items: &[4usize, 5usize, 6usize, 7usize, 8usize],
        }],
    )
});
#[derive(Debug, Clone, Default)]
pub struct ConnectionsParams<'a> {
    pub ids: Option<&'a [i64]>,
    pub source_table: &'a str,
    pub source_id: i64,
    pub supported_providers_only: bool,
    pub active_only: bool,
    pub source_lookup: bool,
}
pub struct ConnectionsRow {
    pub id: i64,
    pub source_table: String,
    pub source_id: i64,
    pub name: Option<String>,
    pub owner_id: i64,
    pub owner_name: String,
    pub is_active: bool,
}
impl<'r> sqlx::FromRow<'r, sqlx::sqlite::SqliteRow> for ConnectionsRow {
    fn from_row(row: &'r sqlx::sqlite::SqliteRow) -> Result<Self, sqlx::Error> {
        Ok(Self {
            id: sqlx::Row::try_get(row, 0)?,
            source_table: sqlx::Row::try_get(row, 1)?,
            source_id: sqlx::Row::try_get(row, 2)?,
            name: sqlx::Row::try_get(row, 3)?,
            owner_id: sqlx::Row::try_get(row, 4)?,
            owner_name: sqlx::Row::try_get(row, 5)?,
            is_active: sqlx::Row::try_get(row, 6)?,
        })
    }
}
pub async fn connections<'e>(
    executor: impl sqlx::Executor<'e, Database = sqlx::Sqlite>,
    params: ConnectionsParams<'_>,
) -> Result<Vec<ConnectionsRow>, sqlx::Error> {
    let args = [
        dynfilter::Arg::Slice(params.ids.map(<[_]>::len)),
        dynfilter::Arg::Active,
        dynfilter::Arg::Active,
        dynfilter::Arg::Flag(params.supported_providers_only),
        dynfilter::Arg::Flag(params.active_only),
        dynfilter::Arg::Flag(params.source_lookup),
    ];
    let (sql, binds) = CONNECTIONS_DYN.build(&args);
    let mut q = sqlx::query_as::<_, ConnectionsRow>(&sql);
    for bind in binds.iter().copied() {
        q = match bind {
            dynfilter::Bind::Elem(0usize, element) => {
                let elem = &params.ids.unwrap()[element];
                q.bind(elem)
            }
            dynfilter::Bind::Arg(1usize) => q.bind(params.source_table),
            dynfilter::Bind::Arg(2usize) => q.bind(params.source_id),
            _ => unreachable!("dynfilter bind plan referenced an unknown argument"),
        };
    }
    let q = q.persistent(false);
    q.fetch_all(executor).await
}
