pub const SIMPLE_FIN_TOKEN_SECRETS: &str = r"SELECT sat.access_url, sat.created_at, sat.id, sat.label, sat.last_synced_at, sat.next_balance_sync_at, sat.next_sync_at, sat.owner_id, sat.sync_cron, sat.updated_at
FROM simplefin_access_tokens sat
WHERE COALESCE(
    CASE CAST(?1 AS TEXT) WHEN 'sync' THEN next_sync_at ELSE next_balance_sync_at END,
    ?2
  ) <= ?2
  AND (
    CAST(?1 AS TEXT) != 'balance'
    OR NOT EXISTS (
      SELECT 1
      FROM simplefin_connections sc
      JOIN connections c ON c.source_table = 'simplefin_connections' AND c.source_id = sc.id
      JOIN accounts a ON a.connection_id = c.id
      WHERE sc.access_token_id = sat.id
        AND a.manual = 0
    )
    OR EXISTS (
      SELECT 1
      FROM simplefin_connections sc
      JOIN connections c ON c.source_table = 'simplefin_connections' AND c.source_id = sc.id
      JOIN accounts a ON a.connection_id = c.id
      WHERE sc.access_token_id = sat.id
        AND a.manual = 0
        AND a.is_closed = 0
    )
  )
ORDER BY id";
